-- YSQ: reconstrucao com textos oficiais + ordem correta + mapa rotativo item->esquema.
-- Fonte: planilha "Questionarios de Esquemas" (abas YSQ + Resultado YSQ).
-- Cria a versao v2-oficial e a ativa; a versao anterior e ARQUIVADA com as 3 respostas
-- preservadas (cada resposta continua pontuando pela versao em que foi respondida).
-- Esquemas/dominios/severidade reaproveitados; scoring segue o gabarito oficial (18x5).

BEGIN;

-- 1. Nova versao em rascunho (herda parametros da versao ativa atual)
SELECT '77777777-7777-7777-7777-7777770a0001', questionnaire_id, 'v2-oficial', 'draft', scoring_method, scale_min, scale_max, instructions, reference_period
FROM public.questionnaire_versions WHERE questionnaire_id='77777777-7777-7777-7777-777777777301' AND status='active';

-- 2. 90 perguntas (textos oficiais, ordem 0..89) na nova versao

-- 3. 90 regras de pontuacao (item -> esquema conforme gabarito oficial rotativo)

-- 4. Copia faixas de severidade da versao ativa atual para a nova versao
SELECT '77777777-7777-7777-7777-7777770a0001', schema_id, domain_id, label, min_score, max_score, color_key, sort_order, metadata
FROM public.severity_ranges WHERE questionnaire_version_id = (SELECT id FROM public.questionnaire_versions WHERE questionnaire_id='77777777-7777-7777-7777-777777777301' AND status='active');

-- 5. Troca a versao ativa (arquiva a antiga, ativa a nova)
UPDATE public.questionnaire_versions SET status='archived', updated_at=timezone('utc',now()) WHERE questionnaire_id='77777777-7777-7777-7777-777777777301' AND status='active';
UPDATE public.questionnaire_versions SET status='active', published_at=timezone('utc',now()), updated_at=timezone('utc',now()) WHERE id='77777777-7777-7777-7777-7777770a0001';

COMMIT;
